compile.workshop:
variables {
    global:
        0: g
}

//Optimizations disabled
rule ("true literal") {
    event {
        Ongoing - Global;
    }
    conditions {
        True != False;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

rule ("false literal") {
    event {
        Ongoing - Global;
    }
    conditions {
        False != False;
    }
    actions {
        Set Global Variable(g, 2);
    }
}

rule ("folded true") {
    event {
        Ongoing - Global;
    }
    conditions {
        Add(1, 2) == 3;
    }
    actions {
        Set Global Variable(g, 3);
    }
}

